/**
 * 搜索与过滤。
 * 按作者选择：只做简单字符串匹配，不引入分词和正则。
 */

/** 关键词是否命中任意一个字段。关键词为空时一律算命中。 */
export function matches_keyword(keyword: string, ...fields: Array<string | null | undefined>): boolean {
  const needle = keyword.trim().toLowerCase();
  if (!needle) return true;
  return fields.some(field => typeof field === 'string' && field.toLowerCase().includes(needle));
}

/** 把一段文本按给定的词组做遮盖，用于截图前的「模糊名词」。 */
export function mask_words(text: string, words: string[]): string {
  let result = text;
  for (const word of words) {
    if (!word) continue;
    result = result.split(word).join(''.repeat(Math.max(1, Math.min(word.length, 8))));
  }
  return result;
}

/** 把一段文本按给定规则做替换，用于文本收藏的「替换名词」。 */
export function replace_words(text: string, rules: Array<{ from: string; to: string }>): string {
  let result = text;
  for (const rule of rules) {
    if (!rule.from) continue;
    result = result.split(rule.from).join(rule.to);
  }
  return result;
}

/** 把用户写的标签名规整成纯标签名，允许写成 <foo> 或 foo。 */
function normalize_tag(raw: string): string {
  return raw.trim().replace(/^</, '').replace(/>$/, '').trim();
}

function escape_reg_exp(text: string): string {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/**
 * 按清洗标签丢掉楼层里的结构，只留标签外的正文。
 *
 * 三种写法都会处理：成对标签、自闭合标签、以及没配对上的孤立开标签。
 * 这样即使模型输出的结构不完整，也不会把整段正文留下或者整段删光。
 */
export function strip_tags(text: string, tags: string[]): string {
  let result = text;
  for (const raw of tags) {
    const tag = normalize_tag(raw);
    if (!tag) continue;
    const name = escape_reg_exp(tag);
    // 标签名后面必须是空白、斜杠或右尖括号。
    // 不能用 \b：词边界只认 ASCII 字母数字，中文标签名（例如「时间」）永远匹配不上。
    const open = `<${name}(?=[\\s/>])[^>]*>`;
    result = result.replace(new RegExp(`${open}[\\s\\S]*?<\\/${name}>`, 'gi'), '');
    result = result.replace(new RegExp(`<${name}(?=[\\s/>])[^>]*\\/>`, 'gi'), '');
    result = result.replace(new RegExp(open, 'gi'), '');
  }
  return result
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}