import { matches_keyword, strip_tags } from '../../core/search';
import * as store from '../../core/store';
import { empty_prefs, type CharacterKey, type CharacterPrefs, type ShotMeta, type TextItem } from '../../core/types';
import type { TavernContext } from '../../tavern/env';
import { confirm_dialog, prompt_dialog } from '../dialog';
import { el, on } from '../dom';
import { excerpt, relative_time } from '../format';
import { icon } from '../icons';
import { toast } from '../toast';
import { render_shot_flow } from './shot_flow';
import { render_shot_tools } from './shot_tools';
import { render_text_detail } from './text_detail';
import { render_text_tools } from './text_tools';

/** 某个角色的收藏库。文本库与截图库各一个标签页，内部再分列表 / 详情 / 文本处理三个视图。 */

export interface WorkspaceHandlers {
  on_back: () => void;
}

interface Message {
  name?: string;
  mes?: string;
  is_user?: boolean;
}

type View =
  | { name: 'list' }
  | { name: 'detail'; id: string }
  | { name: 'tools' }
  | { name: 'shot-tools' }
  | { name: 'shot-flow' };

export function render_workspace(
  context: TavernContext | null,
  character_key: CharacterKey,
  title: string,
  handlers: WorkspaceHandlers,
): HTMLElement {
  let mode: 'text' | 'shot' = 'text';
  let keyword = '';
  let texts: TextItem[] = [];
  let shots: ShotMeta[] = [];
  let picking = false;
  let prefs: CharacterPrefs = empty_prefs(character_key);
  let view: View = { name: 'list' };

  const page = el('section', { class: 'yj-page' });

  /* ---------------------------------------------------------- 列表视图的部件 */

  const back = el('button', {
    class: 'yj-iconbtn yj-ws__back',
    html: icon('back', 19),
    title: '返回角色列表',
    attrs: { type: 'button', 'aria-label': '返回角色列表' },
  });
  on<Event>(back, 'click', () => {
    handlers.on_back();
  });

  const head = el('section', { class: 'yj-ws__head' }, [back, el('div', { class: 'yj-ws__title', text: title })]);

  const seg_text = el('button', { class: 'yj-segment', text: '文本库', attrs: { type: 'button' } });
  const seg_shot = el('button', { class: 'yj-segment', text: '截图库', attrs: { type: 'button' } });
  const segmented = el('div', { class: 'yj-segmented' }, [seg_text, seg_shot]);

  const search_input = el('input', {
    class: 'yj-search__input',
    attrs: { type: 'search', placeholder: '搜索标题或内容', enterkeyhint: 'search' },
  });
  const tune_button = el('button', {
    class: 'yj-iconbtn yj-search__tune',
    html: icon('tune', 19),
    title: '清洗标签与替换名词',
    attrs: { type: 'button', 'aria-label': '清洗标签与替换名词' },
  });
  const add_button = el('button', {
    class: 'yj-iconbtn yj-search__add',
    html: icon('plus', 19),
    title: '从楼层里挑一条收藏',
    attrs: { type: 'button', 'aria-label': '从楼层里挑一条收藏' },
  });
  const search_row = el('div', { class: 'yj-search' }, [
    el('div', { class: 'yj-search__icon', html: icon('search', 17) }),
    search_input,
    tune_button,
    add_button,
  ]);

  const body = el('div', { class: 'yj-ws__body' });

  /* ---------------------------------------------------------- 列表渲染 */

  function empty_state(text: string): HTMLElement {
    return el('div', { class: 'yj-empty' }, [
      el('div', { class: 'yj-empty__mark', html: icon(mode === 'shot' ? 'camera' : 'bookmark', 30) }),
      el('div', { class: 'yj-empty__text', text }),
    ]);
  }

  function text_row(item: TextItem): HTMLElement {
    const trash = el('button', {
      class: 'yj-iconbtn yj-row__action',
      html: icon('trash', 17),
      title: '删除',
      attrs: { type: 'button', 'aria-label': '删除' },
    });
    on<Event>(trash, 'click', event => {
      event.stopPropagation();
      void remove_text(item);
    });
    const row = el('div', { class: 'yj-row yj-row--tappable' }, [
      el('div', { class: 'yj-row__main' }, [
        el('div', { class: 'yj-row__title', text: item.title || '未命名' }),
        el('div', { class: 'yj-row__meta', text: `${relative_time(item.created_at)}  ${excerpt(item.content, 36)}` }),
      ]),
      trash,
    ]);
    on<Event>(row, 'click', () => {
      view = { name: 'detail', id: item.id };
      render();
    });
    return row;
  }

  function shot_card(item: ShotMeta): HTMLElement {
    const star = el('button', {
      class: `yj-iconbtn yj-shot__star${item.starred ? ' is-on' : ''}`,
      html: icon('star', 16),
      title: item.starred ? '取消星标' : '加星标',
      attrs: { type: 'button', 'aria-label': '星标' },
    });
    on<Event>(star, 'click', () => {
      void toggle_star(item);
    });
    const trash = el('button', {
      class: 'yj-iconbtn yj-shot__trash',
      html: icon('trash', 16),
      title: '删除',
      attrs: { type: 'button', 'aria-label': '删除' },
    });
    on<Event>(trash, 'click', () => {
      void remove_shot(item);
    });

    const thumb = el('div', { class: 'yj-shot__thumb' });
    const can_object_url = typeof URL !== 'undefined' && typeof URL.createObjectURL === 'function';
    if (item.thumb && can_object_url) {
      const url = URL.createObjectURL(item.thumb);
      const image = el('img', { attrs: { src: url, alt: '' } });
      on<Event>(image, 'load', () => {
        URL.revokeObjectURL(url);
      });
      thumb.append(image);
    } else {
      thumb.append(el('div', { class: 'yj-shot__placeholder', html: icon('camera', 22) }));
    }

    return el('div', { class: 'yj-shot' }, [
      thumb,
      el('div', { class: 'yj-shot__bar' }, [
        el('div', { class: 'yj-shot__title', text: item.title || '未命名' }),
        star,
        trash,
      ]),
    ]);
  }

  /** 清洗过的正文。清洗标签为空时原样返回。 */
  function cleaned(text: string): string {
    return prefs.clean_tags.length ? strip_tags(text, prefs.clean_tags) : text.trim();
  }

  function picking_list(): HTMLElement {
    const messages = (context?.chat ?? []) as Message[];
    const rows: HTMLElement[] = [];
    for (let index = messages.length - 1; index >= 0 && rows.length < 30; index--) {
      const message = messages[index];
      const raw = typeof message?.mes === 'string' ? message.mes : '';
      const text = cleaned(raw);
      if (!text) continue;
      const row = el('div', { class: 'yj-row yj-row--tappable' }, [
        el('div', { class: 'yj-row__main' }, [
          el('div', { class: 'yj-row__title', text: message.is_user ? '我' : message.name || '角色' }),
          el('div', { class: 'yj-row__meta', text: excerpt(text, 46) }),
        ]),
        el('div', { class: 'yj-row__action', html: icon('plus', 17) }),
      ]);
      on<Event>(row, 'click', () => {
        void collect_from_message(index, text);
      });
      rows.push(row);
    }
    if (!rows.length) {
      return empty_state(
        prefs.clean_tags.length
          ? '按现在的清洗标签过滤之后，这个聊天里没有剩下可以收藏的正文。'
          : '这个聊天里还没有可以收藏的正文。',
      );
    }
    return el('div', { class: 'yj-card' }, rows);
  }

  function render_body(): void {
    body.replaceChildren();
    if (picking) {
      body.append(
        el('div', { class: 'yj-section__head' }, [
          el('div', { class: 'yj-section__title', text: '选择要收藏的楼层' }),
          el('div', { class: 'yj-section__hint', text: prefs.clean_tags.length ? '已按清洗标签过滤' : '只取正文' }),
        ]),
        picking_list(),
      );
      return;
    }
    if (mode === 'text') {
      const visible = texts.filter(item => matches_keyword(keyword, item.title, item.content));
      if (!visible.length) {
        body.append(
          empty_state(
            keyword ? '没有匹配的文本收藏。' : '还没有文本收藏。点右上角的加号，从楼层的正文里挑一条存进来。',
          ),
        );
        return;
      }
      body.append(el('div', { class: 'yj-card' }, visible.map(text_row)));
      return;
    }
    const visible_shots = shots.filter(item => matches_keyword(keyword, item.title));
    if (!visible_shots.length) {
      body.append(empty_state(keyword ? '没有匹配的截图。' : '还没有截图。截图功能在后面的单元接入。'));
      return;
    }
    body.append(el('div', { class: 'yj-shot-grid' }, visible_shots.map(shot_card)));
  }

  function sync_chrome(): void {
    seg_text.classList.toggle('is-active', mode === 'text');
    seg_shot.classList.toggle('is-active', mode === 'shot');
    search_row.style.display = picking ? 'none' : '';
    search_input.setAttribute('placeholder', mode === 'shot' ? '搜索截图标题' : '搜索标题或内容');
    tune_button.style.display = '';
    add_button.style.display = '';
    tune_button.title = mode === 'text' ? '清洗标签与替换名词' : '自定义模糊名词';
    add_button.title = mode === 'text' ? '从楼层里挑一条收藏' : '挑楼层生成截图';
  }

  /* ---------------------------------------------------------- 视图切换 */

  function render(): void {
    if (view.name === 'detail') {
      const item = texts.find(entry => entry.id === (view as { id: string }).id);
      if (item) {
        page.replaceChildren(
          render_text_detail(item, prefs, {
            on_back: () => {
              view = { name: 'list' };
              render();
            },
            on_changed: () => {
              view = { name: 'list' };
              void reload();
            },
          }),
        );
        return;
      }
      view = { name: 'list' };
    }

    if (view.name === 'shot-tools') {
      page.replaceChildren(
        render_shot_tools(prefs, {
          on_back: () => {
            view = { name: 'list' };
            render();
          },
          on_changed: next => {
            prefs = next;
          },
        }),
      );
      return;
    }

    if (view.name === 'shot-flow') {
      page.replaceChildren(
        render_shot_flow(context, character_key, title, prefs, {
          on_close: changed => {
            view = { name: 'list' };
            mode = 'shot';
            if (changed) void reload();
            else render();
          },
        }),
      );
      return;
    }

    if (view.name === 'tools') {
      page.replaceChildren(
        render_text_tools(prefs, {
          on_back: () => {
            view = { name: 'list' };
            render();
          },
          on_changed: next => {
            prefs = next;
          },
        }),
      );
      return;
    }

    page.replaceChildren(head, segmented, search_row, body);
    sync_chrome();
    render_body();
  }

  /* ---------------------------------------------------------- 数据 */

  async function reload(): Promise<void> {
    const [next_texts, next_shots, next_prefs] = await Promise.all([
      store.list_texts(character_key),
      store.list_shots(character_key),
      store.get_prefs(character_key),
    ]);
    if (!page.isConnected) return;
    texts = next_texts;
    shots = next_shots;
    prefs = next_prefs;
    render();
  }

  /* ---------------------------------------------------------- 动作 */

  async function remove_text(item: TextItem): Promise<void> {
    const ok = await confirm_dialog({
      title: '确认删除？',
      message: `「${item.title || '未命名'}」删掉之后就找不回来了。`,
      confirm_text: '删除',
      danger: true,
    });
    if (!ok) return;
    try {
      await store.delete_text(item.id);
      await reload();
    } catch (error) {
      console.warn('[月季管家] 删除文本失败', error);
      toast('删除失败');
    }
  }

  async function remove_shot(item: ShotMeta): Promise<void> {
    const ok = await confirm_dialog({
      title: '确认删除？',
      message: `「${item.title || '未命名'}」连同图片一起删掉，找不回来。`,
      confirm_text: '删除',
      danger: true,
    });
    if (!ok) return;
    try {
      await store.delete_shot(item.id);
      await reload();
    } catch (error) {
      console.warn('[月季管家] 删除截图失败', error);
      toast('删除失败');
    }
  }

  async function toggle_star(item: ShotMeta): Promise<void> {
    try {
      await store.set_shot_starred(item.id, !item.starred);
      await reload();
    } catch (error) {
      console.warn('[月季管家] 更新星标失败', error);
      toast('更新星标失败');
    }
  }

  async function collect_from_message(message_id: number, text: string): Promise<void> {
    const name = await prompt_dialog({
      title: '给这条收藏起个标题',
      message: excerpt(text, 60),
      confirm_text: '收藏',
      input: { placeholder: '例如：雨夜的对话' },
    });
    if (name === null) return;
    try {
      await store.put_text({
        id: store.new_id(),
        character_key,
        title: name || '未命名',
        content: text,
        created_at: Date.now(),
        source_message_id: message_id,
      });
      picking = false;
      view = { name: 'list' };
      keyword = '';
      search_input.value = '';
      await reload();
      toast('已收藏');
    } catch (error) {
      console.warn('[月季管家] 收藏文本失败', error);
      toast('收藏失败');
    }
  }

  /* ---------------------------------------------------------- 事件 */

  on<Event>(seg_text, 'click', () => {
    mode = 'text';
    picking = false;
    render();
  });
  on<Event>(seg_shot, 'click', () => {
    mode = 'shot';
    picking = false;
    render();
  });
  on<Event>(tune_button, 'click', () => {
    view = { name: mode === 'text' ? 'tools' : 'shot-tools' };
    render();
  });
  on<Event>(add_button, 'click', () => {
    if (mode === 'shot') {
      view = { name: 'shot-flow' };
      render();
      return;
    }
    picking = !picking;
    render();
  });
  on<Event>(search_input, 'input', () => {
    keyword = search_input.value;
    render_body();
  });

  render();
  void reload();

  return page;
}
