import * as store from '../../core/store';
import type { CharacterPrefs } from '../../core/types';
import { el, on } from '../dom';
import { icon } from '../icons';
import { toast } from '../toast';

/** 截图侧的设置：自定义模糊名词。 */

export interface ShotToolsHandlers {
  on_back: () => void;
  on_changed: (prefs: CharacterPrefs) => void;
}

export function render_shot_tools(prefs: CharacterPrefs, handlers: ShotToolsHandlers): HTMLElement {
  let current: CharacterPrefs = { ...prefs, blur_words: [...prefs.blur_words] };

  const back = el('button', {
    class: 'yj-iconbtn yj-ws__back',
    html: icon('back', 19),
    title: '返回截图库',
    attrs: { type: 'button', 'aria-label': '返回截图库' },
  });
  on<Event>(back, 'click', () => {
    handlers.on_back();
  });

  const head = el('section', { class: 'yj-ws__head' }, [back, el('div', { class: 'yj-ws__title', text: '截图设置' })]);

  const word_input = el('input', {
    class: 'yj-search__input',
    attrs: { type: 'text', placeholder: '例如 沈知夏', enterkeyhint: 'done' },
  });
  const add_button = el('button', {
    class: 'yj-iconbtn yj-search__add',
    html: icon('plus', 19),
    title: '添加名词',
    attrs: { type: 'button', 'aria-label': '添加名词' },
  });

  const word_list = el('div', { class: 'yj-card' });

  const switch_button = el('button', {
    class: 'yj-btn yj-btn--ghost',
    attrs: { type: 'button' },
  });

  async function persist(next: CharacterPrefs, message: string): Promise<void> {
    current = next;
    render();
    try {
      await store.put_prefs(current);
      handlers.on_changed(current);
      toast(message);
    } catch (error) {
      console.warn('[月季管家] 保存截图设置失败', error);
      toast('保存失败');
    }
  }

  function add_word(): void {
    const value = word_input.value.trim();
    if (!value) {
      toast('先写一个名词');
      return;
    }
    if (current.blur_words.includes(value)) {
      toast('这个名词已经在列表里了');
      return;
    }
    word_input.value = '';
    void persist(
      { ...current, blur_words: [...current.blur_words, value], blur_enabled: true },
      '已添加，截图时会遮掉这个词',
    );
  }

  on<Event>(add_button, 'click', add_word);
  on<KeyboardEvent>(word_input, 'keydown', event => {
    if (event.key === 'Enter') add_word();
  });
  on<Event>(switch_button, 'click', () => {
    void persist(
      { ...current, blur_enabled: !current.blur_enabled },
      current.blur_enabled ? '已关闭模糊' : '已开启模糊',
    );
  });

  function render_words(): void {
    word_list.replaceChildren();
    if (!current.blur_words.length) {
      word_list.classList.add('yj-card--plain');
      word_list.append(el('div', { class: 'yj-empty__text', text: '还没有模糊名词。' }));
      return;
    }
    word_list.classList.remove('yj-card--plain');
    for (const word of current.blur_words) {
      const trash = el('button', {
        class: 'yj-iconbtn yj-row__action yj-row__trash',
        html: icon('trash', 17),
        title: '删除',
        attrs: { type: 'button', 'aria-label': '删除' },
      });
      on<Event>(trash, 'click', () => {
        void persist({ ...current, blur_words: current.blur_words.filter(item => item !== word) }, '已删除');
      });
      word_list.append(
        el('div', { class: 'yj-row' }, [
          el('div', { class: 'yj-row__main' }, [el('div', { class: 'yj-row__title', text: word })]),
          trash,
        ]),
      );
    }
  }

  const container = el('section', { class: 'yj-page' });

  function render(): void {
    render_words();
    switch_button.textContent = current.blur_enabled ? '模糊已开启，点此关闭' : '模糊已关闭，点此开启';
    container.replaceChildren(
      head,
      el('div', { class: 'yj-section' }, [
        el('div', { class: 'yj-section__head' }, [
          el('div', { class: 'yj-section__title', text: '自定义模糊名词' }),
          el('div', { class: 'yj-section__hint', text: '只看不改' }),
        ]),
        el('div', {
          class: 'yj-note',
          text: '这些名词会遮掉：截图时自动识别并覆盖成方块，原聊天内容一点不动。适合处理不想出现在图片里的人名或敏感词。',
        }),
        el('div', { class: 'yj-search' }, [word_input, add_button]),
        word_list,
        el('div', { class: 'yj-section' }, [switch_button]),
      ]),
    );
  }

  render();
  return container;
}
