import { mask_words, strip_tags } from '../../core/search';
import { render_shot, type ShotRenderResult } from '../../core/shot_canvas';
import type { ShotBlock, ShotStyle } from '../../core/shot_layout';
import * as store from '../../core/store';
import type { CharacterKey, CharacterPrefs } from '../../core/types';
import type { TavernContext } from '../../tavern/env';
import { prompt_dialog } from '../dialog';
import { download_blob, shot_filename } from '../download';
import { el, on } from '../dom';
import { excerpt } from '../format';
import { icon } from '../icons';
import { toast } from '../toast';

/**
 * 截图流程：挑楼层  生成预览  保存到本地或收进图库。
 *
 * 这里选楼层用的是面板内的列表，不去往聊天页面注入按钮。
 * 楼层 DOM 结构随酒馆版本变化，注入按钮在手机上也不好点，面板内选择能本地自测。
 */

export interface ShotFlowHandlers {
  /** 收进图库或取消之后，回到截图库。 */
  on_close: (changed: boolean) => void;
}

interface Message {
  name?: string;
  mes?: string;
  is_user?: boolean;
}

/** 阅读卡片的排版参数。宽度是逻辑像素，实际像素密度由渲染器按内存预算决定。 */
const SHOT_STYLE: ShotStyle = {
  width: 760,
  font_size: 26,
  line_height: 44,
  padding: 44,
  block_gap: 26,
};

/** 一次最多能挑多少层。太多了手机上既慢又容易超预算。 */
const MAX_PICKS = 60;

export function render_shot_flow(
  context: TavernContext | null,
  character_key: CharacterKey,
  character_name: string,
  prefs: CharacterPrefs,
  handlers: ShotFlowHandlers,
): HTMLElement {
  const messages = (context?.chat ?? []) as Message[];
  const selected = new Set<number>();
  let title = '';
  let busy = false;
  let result: ShotRenderResult | null = null;
  let error = '';
  let preview_url: string | null = null;

  const page = el('section', { class: 'yj-page' });

  function back(on_click: () => void, label: string): HTMLElement {
    const button = el('button', {
      class: 'yj-iconbtn yj-ws__back',
      html: icon('back', 19),
      title: label,
      attrs: { type: 'button', 'aria-label': label },
    });
    on<Event>(button, 'click', on_click);
    return button;
  }

  /** 把选中的楼层整理成画布要用的段落。清洗标签与模糊名词都在这里生效。 */
  function build_blocks(): ShotBlock[] {
    const blocks: ShotBlock[] = [];
    for (const id of [...selected].sort((lhs, rhs) => lhs - rhs)) {
      const message = messages[id];
      if (!message) continue;
      let text = typeof message.mes === 'string' ? message.mes : '';
      if (prefs.clean_tags.length) text = strip_tags(text, prefs.clean_tags);
      if (prefs.blur_enabled && prefs.blur_words.length) text = mask_words(text, prefs.blur_words);
      text = text.trim();
      if (!text) continue;
      blocks.push({
        name: message.is_user ? '我' : message.name || '旁白',
        text,
        is_user: message.is_user === true,
      });
    }
    return blocks;
  }

  function preview_text(id: number): string {
    const message = messages[id];
    let text = typeof message?.mes === 'string' ? message.mes : '';
    if (prefs.clean_tags.length) text = strip_tags(text, prefs.clean_tags);
    if (prefs.blur_enabled && prefs.blur_words.length) text = mask_words(text, prefs.blur_words);
    return text.trim();
  }

  /* ---------------------------------------------------------- 选择楼层 */

  function select_view(): HTMLElement {
    const rows: HTMLElement[] = [];
    for (let index = messages.length - 1; index >= 0; index--) {
      const message = messages[index];
      const text = preview_text(index);
      if (!text) continue;
      const picked = selected.has(index);
      const row = el('div', { class: `yj-row yj-row--tappable${picked ? ' is-picked' : ''}` }, [
        el('div', { class: `yj-pick${picked ? ' is-on' : ''}`, html: icon('check', 14) }),
        el('div', { class: 'yj-row__main' }, [
          el('div', { class: 'yj-row__title', text: message.is_user ? '我' : message.name || '旁白' }),
          el('div', { class: 'yj-row__meta', text: excerpt(text, 42) }),
        ]),
      ]);
      on<Event>(row, 'click', () => {
        if (selected.has(index)) selected.delete(index);
        else if (selected.size >= MAX_PICKS) toast(`一次最多挑 ${MAX_PICKS} 层`);
        else selected.add(index);
        render();
      });
      rows.push(row);
    }

    const head = el('section', { class: 'yj-ws__head' }, [
      back(() => {
        handlers.on_close(false);
      }, '返回截图库'),
      el('div', { class: 'yj-ws__title', text: '挑要截的楼层' }),
    ]);

    const hint = el('div', { class: 'yj-note' }, [
      el('div', { text: '可以跳着挑，也可以一次挑很多层。挑中的楼层会按顺序无缝拼成一段连续正文。' }),
      el('div', {
        text: prefs.clean_tags.length
          ? '已按清洗标签过滤，状态栏这类结构不会进图片。'
          : '只取正文，状态栏和时间组件不进图片。',
      }),
    ]);

    const actions = el('div', { class: 'yj-detail__actions' }, [
      (() => {
        const button = el('button', {
          class: 'yj-btn yj-btn--primary',
          text: selected.size ? `生成预览（${selected.size} 层）` : '先挑楼层',
          attrs: { type: 'button' },
        });
        if (!selected.size) button.setAttribute('disabled', 'true');
        on<Event>(button, 'click', () => {
          if (!selected.size) return;
          void generate();
        });
        return button;
      })(),
    ]);

    if (!rows.length) {
      return el('section', { class: 'yj-page' }, [
        head,
        el('div', { class: 'yj-empty' }, [
          el('div', { class: 'yj-empty__mark', html: icon('camera', 30) }),
          el('div', {
            class: 'yj-empty__text',
            text: prefs.clean_tags.length
              ? '按现在的清洗标签过滤之后，这个聊天里没有剩下可以截的正文。'
              : '这个聊天里还没有可以截的正文。',
          }),
        ]),
      ]);
    }

    return el('section', { class: 'yj-page' }, [head, hint, el('div', { class: 'yj-card' }, rows), actions]);
  }

  /* ---------------------------------------------------------- 预览 */

  function preview_view(): HTMLElement {
    const head = el('section', { class: 'yj-ws__head' }, [
      back(() => {
        if (preview_url) URL.revokeObjectURL(preview_url);
        preview_url = null;
        result = null;
        render();
      }, '返回重挑'),
      el('div', { class: 'yj-ws__title', text: '预览' }),
    ]);

    const parts: HTMLElement[] = [head];

    if (busy) {
      parts.push(el('div', { class: 'yj-empty' }, [el('div', { class: 'yj-empty__text', text: '正在生成图片' })]));
      return el('section', { class: 'yj-page' }, parts);
    }

    if (error) {
      parts.push(
        el('div', { class: 'yj-empty' }, [
          el('div', { class: 'yj-empty__mark', html: icon('camera', 30) }),
          el('div', { class: 'yj-empty__text', text: error }),
        ]),
      );
      return el('section', { class: 'yj-page' }, parts);
    }

    if (!result?.blob) {
      parts.push(
        el('div', { class: 'yj-empty' }, [el('div', { class: 'yj-empty__text', text: '图片没有生成成功。' })]),
      );
      return el('section', { class: 'yj-page' }, parts);
    }

    if (preview_url) URL.revokeObjectURL(preview_url);
    preview_url = URL.createObjectURL(result.blob);
    const image = el('img', { class: 'yj-preview__image', attrs: { src: preview_url, alt: '截图预览' } });
    parts.push(el('div', { class: 'yj-preview' }, [image]));

    parts.push(
      el('div', {
        class: 'yj-row__meta',
        text: `${result.width}  ${result.height} 像素  用了 ${result.used_blocks} 层`,
      }),
    );

    if (result.truncated) {
      parts.push(
        el('div', { class: 'yj-note yj-note--warn' }, [
          el('div', {
            text: `内容太长，这台设备一次画不完。图里只有前 ${result.used_blocks} 层，共挑了 ${result.total_blocks} 层。想要完整图请分两次截。`,
          }),
        ]),
      );
    }

    const title_input = el('input', {
      class: 'yj-input',
      attrs: { type: 'text', placeholder: '给这张图起个标题（可不填）', value: title },
    });
    on<Event>(title_input, 'input', () => {
      title = title_input.value;
    });
    parts.push(el('div', { class: 'yj-editor__field' }, [title_input]));

    const save_local = el('button', {
      class: 'yj-btn yj-btn--ghost',
      text: '保存到本地',
      attrs: { type: 'button' },
    });
    on<Event>(save_local, 'click', () => {
      if (!result?.blob) return;
      download_blob(result.blob, shot_filename(title || character_name));
      toast('已生成图片，看看浏览器的下载');
    });

    const collect = el('button', {
      class: 'yj-btn yj-btn--primary',
      text: '收进图库',
      attrs: { type: 'button' },
    });
    on<Event>(collect, 'click', () => {
      void collect_to_library();
    });

    parts.push(el('div', { class: 'yj-detail__actions' }, [save_local, collect]));
    return el('section', { class: 'yj-page' }, parts);
  }

  /* ---------------------------------------------------------- 动作 */

  async function generate(): Promise<void> {
    busy = true;
    error = '';
    render();
    const blocks = build_blocks();
    if (!blocks.length) {
      busy = false;
      error = '挑中的楼层清洗之后没有剩下正文。';
      render();
      return;
    }
    try {
      result = await render_shot({
        blocks,
        style: SHOT_STYLE,
        title,
        footer: `${character_name}  ${new Date().toLocaleDateString('zh-CN')}`,
        theme: 'light',
      });
    } catch (failure) {
      console.warn('[月季管家] 生成截图失败', failure);
      error = failure instanceof Error ? failure.message : '生成图片失败。';
    }
    busy = false;
    render();
  }

  async function collect_to_library(): Promise<void> {
    if (!result?.blob) return;
    let name = title.trim();
    if (!name) {
      const answer = await prompt_dialog({
        title: '给这张截图起个标题',
        confirm_text: '收藏',
        input: { placeholder: '例如：雨夜的对话' },
      });
      if (answer === null) return;
      name = answer || '未命名';
      title = name;
    }
    try {
      await store.put_shot(
        {
          id: store.new_id(),
          character_key,
          title: name,
          created_at: Date.now(),
          width: result.width,
          height: result.height,
          bytes: result.blob.size,
          starred: false,
          thumb: result.thumb,
        },
        result.blob,
      );
      toast('已收进图库');
      handlers.on_close(true);
    } catch (failure) {
      console.warn('[月季管家] 收藏截图失败', failure);
      toast('收藏失败');
    }
  }

  function render(): void {
    page.replaceChildren(result || busy || error ? preview_view() : select_view());
  }

  render();
  return page;
}
